// Package wordy scores how much a string reads like natural-language or
// programming words, using a character-bigram model. Random secrets score
// low; identifiers like "isOnDemandRevalidate" or "SecurityProfiles" score high.
//
// The model in table.go is generated by ./gen from a corpus of source code
// and documentation (go generate ./internal/wordy).
package wordy

//go:generate sh -c "go run ./gen -out table.go -max-files 12000 /usr/lib/python3.13 $(go env GOROOT)/src"

// index maps '^' (start), 'a'..'z', '$' (end) to 0..27.
func index(c byte) int {
	switch {
	case c == '^':
		return 0
	case c >= 'a' && c <= 'z':
		return int(c-'a') + 1
	case c == '$':
		return 27
	}
	return -1
}

// Tokens splits s into alphabetic words, breaking on case changes:
// "parseHTTPRequest2xx" -> parse, HTTP, Request, xx.
func Tokens(s string) []string {
	var out []string
	isUp := func(c byte) bool { return c >= 'A' && c <= 'Z' }
	isLo := func(c byte) bool { return c >= 'a' && c <= 'z' }
	i := 0
	for i < len(s) {
		if !isUp(s[i]) && !isLo(s[i]) {
			i++
			continue
		}
		j := i
		if isUp(s[j]) {
			for j < len(s) && isUp(s[j]) {
				j++
			}
			if j < len(s) && isLo(s[j]) && j-i > 1 {
				j-- // "HTTPRequest": last capital starts the next word
			} else if j < len(s) && isLo(s[j]) {
				for j < len(s) && isLo(s[j]) {
					j++
				}
			}
		} else {
			for j < len(s) && isLo(s[j]) {
				j++
			}
		}
		out = append(out, s[i:j])
		i = j
	}
	return out
}

// Score is the mean log-probability per bigram of one word (higher = more word-like).
func Score(w string) float64 {
	prev := 0
	var sum float64
	n := 0
	for i := 0; i <= len(w); i++ {
		cur := 27
		if i < len(w) {
			c := w[i]
			if c >= 'A' && c <= 'Z' {
				c += 32
			}
			cur = index(c)
			if cur < 0 {
				continue
			}
		}
		sum += float64(table[prev][cur])
		prev = cur
		n++
	}
	if n == 0 {
		return -10
	}
	return sum / float64(n)
}

// Threshold separates word-like runs from random ones (tuned on labeled data).
const Threshold = -3.2

// Wordiness returns the fraction of letters in s that belong to word-like
// runs of at least 3 letters.
func Wordiness(s string) float64 {
	letters := 0
	for i := 0; i < len(s); i++ {
		if c := s[i]; c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' {
			letters++
		}
	}
	if letters == 0 {
		return 0
	}
	good := 0
	for _, w := range Tokens(s) {
		if len(w) >= 3 && Score(w) > Threshold {
			good += len(w)
		}
	}
	return float64(good) / float64(letters)
}
